"""Reviewed non-AI example, generated by the same CLI/web MCP path."""
import hashlib
import json
import math
from pathlib import Path

APP_ROOT = Path(__file__).resolve().parents[2]


def build_example(service):
    source = APP_ROOT / 'tests/research_fixtures/mannkendall/source'
    provenance = json.loads((source.parent / 'provenance.json').read_text(encoding='utf-8'))
    for relative, expected in provenance['source_files'].items():
        if relative == 'README.md':
            documentation = json.loads((APP_ROOT / 'tests/research_fixtures/documentation.json').read_text(encoding='utf-8'))
            expected = documentation['file_sha256']['mannkendall/source/README.md']
        path = source / relative
        if path.is_symlink() or not path.resolve().is_relative_to(source.resolve()):
            raise ValueError('Invalid Mann-Kendall source path')
        if hashlib.sha256(path.read_bytes()).hexdigest() != expected:
            raise ValueError('Mann-Kendall source hash mismatch')
    built = service.build_code_mcp(str(source),
        ['mannkendall_adapter:original_trend', 'mannkendall_adapter:seasonal_trend'], 'mannkendall-statistics')
    return Path(built['project_path'])


def run_demo(service, python_executable):
    if not Path(python_executable).is_file():
        raise ValueError('Install the independent Mann-Kendall environment and provide its Python executable')
    project = build_example(service)
    reference = json.loads((APP_ROOT / 'tests/research_fixtures/mannkendall/reference.json').read_text(encoding='utf-8'))
    records = []
    for case in reference['cases']:
        native = service.test_code_mcp(str(project), 'mannkendall_adapter__' + case['tool'], case['arguments'], python_executable)
        value = (native.get('result') or {}).get('data', {}).get('native_result')
        if 'expected' in case:
            expected = case['expected']
            passed = native.get('decision') == 'completed' and isinstance(value, dict) and set(value) == set(expected)
            if passed:
                passed = all(value[k] == v if type(v) in (bool, str) else
                    isinstance(value[k], (int, float)) and not isinstance(value[k], bool) and
                    math.isfinite(value[k]) and math.isclose(value[k], v, rel_tol=1e-12, abs_tol=1e-12)
                    for k, v in expected.items())
        else:
            passed = native.get('decision') == 'execution_error' and case['error_contains'] in native.get('error', '')
        records.append({'case': case['id'], 'passed': bool(passed), 'expected_error': 'expected' not in case,
                        'native_result': value, 'native_record': native})
    report = {'success': all(c['passed'] for c in records), 'project_path': str(project),
              'transport': 'real_stdio_fastmcp_client', 'local_model_called': False,
              'inputs': 'explicit synthetic arrays, not measured climate observations', 'cases': records}
    destination = project / 'demo-result.json'
    destination.write_text(json.dumps(report, ensure_ascii=False, indent=2, allow_nan=False), encoding='utf-8')
    return {'success': report['success'], 'project_path': str(project), 'report_path': str(destination),
            'cases': [{k: c[k] for k in ('case', 'passed', 'expected_error', 'native_result')} for c in records]}
